#include "constant.h"

/* PNG */
static const wxString s_constant_16_png = wxT("");

wxIcon ibValueMetaObjectConstant::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectConstant::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_constant_16_png, wxSize(16, 16));
	
	return icon;
}